import{_ as t,o,c as n,a2 as i}from"./chunks/framework.BEUshCVJ.js";const u=JSON.parse('{"title":"Recognition and hint quality","description":"","frontmatter":{},"headers":[],"relativePath":"troubleshooting/quality.md","filePath":"troubleshooting/quality.md","lastUpdated":1792975530000}'),s={name:"troubleshooting/quality.md"};function r(a,e,l,g,h,d){return o(),n("div",null,[...e[0]||(e[0]=[i('<h1 id="recognition-and-hint-quality" tabindex="-1">Recognition and hint quality <a class="header-anchor" href="#recognition-and-hint-quality" aria-label="Permalink to &quot;Recognition and hint quality&quot;">​</a></h1><p>This page helps when hints are missing, appear for the wrong sentences, or recognition gets words wrong.</p><h2 id="no-hints" tabindex="-1">A question was asked but no hints appeared <a class="header-anchor" href="#no-hints" aria-label="Permalink to &quot;A question was asked but no hints appeared {#no-hints}&quot;">​</a></h2><p><strong>Possible causes</strong></p><ol><li>Listening is paused or the system sound level is flat.</li><li><strong>Only questions directed at me</strong> is on and the question looked meant for someone else.</li><li>The question was very short or rhetorical (&quot;right?&quot;, &quot;okay?&quot;); these are ignored on purpose.</li><li>Hint generation failed or timed out (<a href="/meetcue/troubleshooting/error-codes#mc-llm-001">MC-LLM-001</a>, <a href="/meetcue/troubleshooting/error-codes#mc-llm-005">MC-LLM-005</a>).</li><li>The budget limit was reached and <strong>Pause hint generation</strong> is selected (<a href="/meetcue/troubleshooting/error-codes#mc-bud-002">MC-BUD-002</a>).</li></ol><p><strong>Check</strong></p><ol><li>Look at the status dot in the panel title bar: green means listening.</li><li>Open <strong>Settings › Diagnostics</strong>. Recent events show whether the sentence was recognised and how detection decided.</li></ol><p><strong>Fix</strong></p><ol><li>Start listening with <code>Ctrl+Alt+Space</code>; fix flat levels with <a href="/meetcue/troubleshooting/audio">Audio and devices</a>.</li><li>Turn off <strong>Only questions directed at me</strong> if you want hints for every question.</li><li>For errors, follow the fix shown with the error code.</li></ol><p><strong>Still not solved?</strong> <a href="/meetcue/troubleshooting/diagnostics">Export diagnostics</a> and <a href="https://github.com/Amazingkenneth/meetcue/issues/new?template=bug.yml" target="_blank" rel="noreferrer">open an issue</a>.</p><h2 id="too-many" tabindex="-1">Hints appear for small talk <a class="header-anchor" href="#too-many" aria-label="Permalink to &quot;Hints appear for small talk {#too-many}&quot;">​</a></h2><p><strong>Possible causes</strong></p><ol><li>The detection model is too small for your meetings.</li><li>Several people ask each other questions and they aren&#39;t meant for you.</li></ol><p><strong>Check</strong></p><ol><li>Open the grey question text in the conversation to see why it was detected.</li></ol><p><strong>Fix</strong></p><ol><li>Turn on <strong>Settings › Hints › Only questions directed at me</strong>.</li><li>Fill in <strong>My role</strong> so detection knows what you are expected to answer.</li><li>Choose a stronger detection model in <strong>Settings › Providers &amp; cost</strong>.</li></ol><p><strong>Still not solved?</strong> <a href="/meetcue/troubleshooting/diagnostics">Export diagnostics</a> and <a href="https://github.com/Amazingkenneth/meetcue/issues/new?template=bug.yml" target="_blank" rel="noreferrer">open an issue</a>.</p><h2 id="recognition" tabindex="-1">Names and terms are recognised wrongly <a class="header-anchor" href="#recognition" aria-label="Permalink to &quot;Names and terms are recognised wrongly {#recognition}&quot;">​</a></h2><p><strong>Possible causes</strong></p><ol><li>The meeting languages are set wrong.</li><li>Product names and acronyms are unknown to the recognition model.</li><li>The audio is quiet or noisy.</li></ol><p><strong>Check</strong></p><ol><li>Open <strong>Settings › Audio › Meeting languages</strong>.</li><li>Watch the transcript in the conversation while someone speaks.</li></ol><p><strong>Fix</strong></p><ol><li>Choose the languages actually spoken. Use <strong>Chinese and English</strong> when both appear in the same sentence.</li><li>Add an agenda or project notes as <a href="/meetcue/guide/materials">briefing material</a>. Distinctive terms are passed to the recognition service as hints.</li><li>Try the other recognition provider: Soniox handles Chinese and English mixed in one sentence well.</li></ol><p><strong>Still not solved?</strong> <a href="/meetcue/troubleshooting/diagnostics">Export diagnostics</a> and <a href="https://github.com/Amazingkenneth/meetcue/issues/new?template=bug.yml" target="_blank" rel="noreferrer">open an issue</a>.</p><h2 id="split" tabindex="-1">One question is split into two <a class="header-anchor" href="#split" aria-label="Permalink to &quot;One question is split into two {#split}&quot;">​</a></h2><p><strong>Possible causes</strong></p><ol><li>The speaker pauses mid-question for longer than the sentence-end silence.</li></ol><p><strong>Check</strong></p><ol><li>Look for two consecutive question blocks where the first one ends mid-sentence.</li></ol><p><strong>Fix</strong></p><ol><li>Increase <strong>Settings › Audio › Advanced › Sentence end after silence</strong>, for example from 700 to 1000 ms. Hints then appear slightly later.</li></ol><p><strong>Still not solved?</strong> <a href="/meetcue/troubleshooting/diagnostics">Export diagnostics</a> and <a href="https://github.com/Amazingkenneth/meetcue/issues/new?template=bug.yml" target="_blank" rel="noreferrer">open an issue</a>.</p>',34)])])}const p=t(s,[["render",r]]);export{u as __pageData,p as default};
